import type { SeedTables, SeedValue } from './seed-values';

export const SEED_SQL_HEADER =
  '-- Generated by scripts/generate-upgrade-seed.ts from src/backend/testing/upgrade/seed-rows.ts.\n' +
  '-- Do not edit by hand: change the rows and run the generator again.\n' +
  '-- Rows the last published release could have written, one or a few per table.\n';

function quote(text: string): string {
  return `'${text.replaceAll("'", "''")}'`;
}

/** The SQL literal for one value; objects and arrays are stored as JSON text. */
export function sqlLiteral(value: SeedValue): string {
  if (value === null) {
    return 'NULL';
  }
  if (typeof value === 'boolean') {
    return value ? '1' : '0';
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new Error(`Seed values must be finite numbers, got ${value}`);
    }
    return String(value);
  }
  return quote(typeof value === 'string' ? value : JSON.stringify(value));
}

/** One INSERT per row, tables in the order given. */
export function renderSeedSql(tables: SeedTables): string {
  const sections = Object.entries(tables).map(([table, rows]) => {
    if (rows.length === 0) {
      throw new Error(`Seed table ${table} has no rows`);
    }
    const statements = rows.map((row) => {
      const entries = Object.entries(row);
      return (
        `INSERT INTO "${table}" (${entries.map(([column]) => `"${column}"`).join(', ')}) ` +
        `VALUES (${entries.map(([, value]) => sqlLiteral(value)).join(', ')});`
      );
    });
    return `-- ${table}\n${statements.join('\n')}\n`;
  });
  return `${SEED_SQL_HEADER}\n${sections.join('\n')}`;
}
